const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={user:null,categories:[],accounts:[],cards:[],transactions:[],budgets:[],goals:[],recurring:[],calendarEvents:[],calendarSelectedDate:null,dashboard:null,page:"dashboard",month:todayLocal().slice(0,7),authMode:"login",editingReminderId:null};
const brl=new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}),money=v=>brl.format(Number(v||0));
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const dateBR=v=>v?new Date(String(v).slice(0,10)+"T12:00:00").toLocaleDateString("pt-BR"):"—";
const todayLocal=()=>new Intl.DateTimeFormat("sv-SE",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
const monthName=v=>{const a=v.split("-");return new Date(+a[0],+a[1]-1,1).toLocaleDateString("pt-BR",{month:"long",year:"numeric"});};
const symbol=n=>({Moradia:"⌂",Alimentação:"◉",Transporte:"↗",Saúde:"✚",Educação:"▤",Lazer:"✧",Serviços:"▧",Compras:"◇",Salário:"↙","Renda extra":"✦",Investimentos:"↗"}[n]||"◌");
let toastTimer;
function toast(m,error){const e=$("#toast");e.textContent=m;e.classList.toggle("error",!!error);e.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove("show"),3200);}
async function api(url,opt){opt=opt||{};opt.credentials="same-origin";opt.headers=Object.assign({"Content-Type":"application/json"},opt.headers||{});const r=await fetch(url,opt);let d={};try{d=await r.json();}catch{}if(!r.ok){if(r.status===401&&url!=="/api/auth/login"&&url!=="/api/auth/register")showAuth();throw new Error(d.error||"Não foi possível concluir a operação.");}return d;}
function showAuth(){$("#app-shell").hidden=true;$("#auth-screen").hidden=false;state.user=null;}
function setTheme(t,save){const v=t==="system"?(matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"):t;document.documentElement.dataset.theme=v;localStorage.setItem("tvc-theme-choice-v2",t);$$("[data-theme-choice]").forEach(b=>b.classList.toggle("selected",b.dataset.themeChoice===t));if(save&&state.user)api("/api/me",{method:"PATCH",body:JSON.stringify({theme:t})}).catch(()=>{});}
function authMode(mode){state.authMode=mode;const reg=mode==="register";$("#auth-title").textContent=reg?"Crie sua conta":"Acesse sua conta";$("#auth-subtitle").textContent=reg?"Comece a organizar sua vida financeira.":"Entre para acompanhar suas finanças.";$("#name-field").hidden=!reg;$("#auth-submit").textContent=reg?"Criar minha conta →":"Entrar na minha conta →";$("#auth-switch-copy").textContent=reg?"Já possui uma conta?":"Ainda não tem uma conta?";$("#auth-switch").textContent=reg?"Fazer login":"Criar conta grátis";$("#auth-form").elements.password.autocomplete=reg?"new-password":"current-password";$("#auth-error").hidden=true;}
$("#auth-switch").onclick=()=>authMode(state.authMode==="login"?"register":"login");
$("#auth-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b={email:f.get("email"),password:f.get("password")};if(state.authMode==="register")b.fullName=f.get("fullName");$("#auth-submit").disabled=true;$("#auth-submit").textContent="Aguarde...";try{await api("/api/auth/"+state.authMode,{method:"POST",body:JSON.stringify(b)});await boot();}catch(x){$("#auth-error").textContent=x.message;$("#auth-error").hidden=false;}finally{$("#auth-submit").disabled=false;$("#auth-submit").textContent=state.authMode==="register"?"Criar minha conta →":"Entrar na minha conta →";}};
async function boot(){try{const m=await api("/api/me");state.user=m.user;$("#auth-screen").hidden=true;$("#app-shell").hidden=false;$("#sidebar-user-name").textContent=m.user.fullName||"Minha conta";$("#sidebar-user-email").textContent=m.user.email;$("#user-avatar").textContent=(m.user.fullName||m.user.email).charAt(0).toUpperCase();$("#welcome-title").textContent="Olá, "+((m.user.fullName||"").split(" ")[0]||"bem-vindo")+"!";$("#profile-form").elements.fullName.value=m.user.fullName||"";$("#profile-email").value=m.user.email;setTheme(localStorage.getItem("tvc-theme-choice-v2")||"light",false);await refresh();showPage(state.page);}catch{showAuth();}}
async function refresh(){const m=state.month;try{const generated=await api("/api/recurring/auto-generate",{method:"POST",body:"{}"});if(generated.created>0)toast(generated.created+" lançamento(s) recorrente(s) gerado(s) automaticamente.");}catch(err){console.warn("Auto geração de recorrências:",err.message);toast("Não foi possível atualizar as recorrências automaticamente.",true);}const r=await Promise.all([api("/api/categories"),api("/api/accounts"),api("/api/cards"),api("/api/transactions?month="+m),api("/api/budgets?month="+m),api("/api/goals"),api("/api/recurring"),api("/api/dashboard?month="+m),api("/api/calendar?month="+m)]);state.categories=r[0].categories;state.accounts=r[1].accounts;state.cards=r[2].cards;state.transactions=r[3].transactions;state.budgets=r[4].budgets;state.goals=r[5].goals;state.recurring=r[6].recurring;state.dashboard=r[7];state.calendarEvents=r[8].events||[];if(!state.calendarSelectedDate||state.calendarSelectedDate.slice(0,7)!==m){const todaySP=new Intl.DateTimeFormat("sv-SE",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());state.calendarSelectedDate=todaySP.slice(0,7)===m?todaySP:m+"-01";}renderAll();}
function showPage(p){state.page=p;$$(".page").forEach(x=>x.classList.toggle("active",x.id==="page-"+p));$$("[data-page]").forEach(x=>x.classList.toggle("active",x.dataset.page===p));const titles={dashboard:"Visão geral",calendar:"Calendário financeiro",transactions:"Lançamentos",accounts:"Minhas contas",cards:"Cartões",budgets:"Orçamentos",goals:"Metas e sonhos",recurring:"Despesas fixas",reports:"Relatórios",settings:"Configurações"};$("#page-title").textContent=titles[p]||"TVC Control";$("#month-control").hidden=!["dashboard","calendar","transactions","reports"].includes(p);if(p==="transactions")renderTransactions();if(p==="calendar")renderCalendar();}
$$("[data-page]").forEach(b=>b.onclick=()=>showPage(b.dataset.page));$$("[data-go]").forEach(b=>b.onclick=()=>showPage(b.dataset.go));
$("#month-picker").value=state.month;$("#month-picker").onchange=async e=>{if(e.target.value){state.month=e.target.value;state.calendarSelectedDate=state.month+"-01";await refresh();}};
$("#today-label").textContent=new Date().toLocaleDateString("pt-BR",{weekday:"long",day:"2-digit",month:"long"}).toUpperCase();$("#year").textContent=new Date().getFullYear();
function renderAll(){renderDashboard();renderCalendar();renderTransactions();renderAccounts();renderCards();renderBudgets();renderGoals();renderRecurring();renderReports();}
function renderDashboardAccounts(){
 const list=$("#dashboard-accounts-list"),total=$("#dashboard-accounts-total");
 if(!list||!total)return;
 const accounts=state.dashboard?.accounts||state.accounts||[];
 const balance=state.dashboard?.balance??accounts.reduce((sum,a)=>sum+Number(a.current_balance||0),0);
 total.textContent=money(balance);
 list.innerHTML=accounts.length?accounts.slice(0,4).map(a=>{
  const type=String(a.account_type||"").toLowerCase(),icon=/poup|saving/.test(type)?"◉":/invest/.test(type)?"↗":/carteira|dinheiro/.test(type)?"◈":"▣";
  const subtitle=[accountType(a.account_type),a.institution].filter(Boolean).join(" · ");
  const projected=Number(a.projected_balance??a.current_balance);
  return '<button type="button" class="dashboard-account-row" data-edit-account="'+esc(a.id)+'"><span class="dashboard-account-icon">'+icon+'</span><span class="dashboard-account-copy"><b>'+esc(a.name)+'</b><small>'+esc(subtitle)+'</small></span><span class="dashboard-account-values"><b class="'+(Number(a.current_balance)<0?"negative":"")+'">'+money(a.current_balance)+'</b><small class="'+(projected<0?"negative":"positive")+'">Livre: '+money(projected)+'</small></span></button>';
 }).join(""):'<div class="empty-state">Nenhuma conta cadastrada. <button class="link-button" data-create="account">Adicionar conta →</button></div>';
}
function renderDashboardMiniCalendar(){
 const monthLabel=$("#dashboard-calendar-month"),weekdays=$("#dashboard-calendar-weekdays"),grid=$("#dashboard-calendar-grid");
 if(!monthLabel||!weekdays||!grid)return;
 const [year,month]=state.month.split("-").map(Number),daysInMonth=new Date(year,month,0).getDate(),offset=new Date(year,month-1,1).getDay();
 const today=new Intl.DateTimeFormat("sv-SE",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
 const eventsByDate={};
 (state.calendarEvents||[]).forEach(event=>{const date=String(event.event_date).slice(0,10);(eventsByDate[date]||(eventsByDate[date]=[])).push(event);});
 monthLabel.textContent=new Date(year,month-1,1).toLocaleDateString("pt-BR",{month:"long",year:"numeric"});
 weekdays.innerHTML=["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map(day=>'<span>'+day+'</span>').join("");
 const cells=[];
 for(let i=0;i<offset;i++)cells.push('<span class="mini-calendar-day empty" aria-hidden="true"></span>');
 for(let day=1;day<=daysInMonth;day++){
  const date=state.month+"-"+String(day).padStart(2,"0"),items=eventsByDate[date]||[],selected=date===state.calendarSelectedDate,isToday=date===today;
  const dots=items.slice(0,3).map(event=>'<i class="'+(event.kind==="income"?"income":event.kind==="transfer"?"transfer":"expense")+'"></i>').join("");
  cells.push('<button type="button" class="mini-calendar-day '+(selected?"selected ":"")+(isToday?"today ":"")+(items.length?"has-events":"")+'" data-dashboard-calendar-day="'+date+'" aria-label="'+date+(items.length?", "+items.length+" compromisso(s)":"")+'"><span>'+day+'</span><i class="mini-calendar-dots">'+dots+'</i></button>');
 }
 grid.innerHTML=cells.join("");
}
function renderDashboard(){
 const d=state.dashboard;if(!d)return;
 const alertBox=$("#dashboard-alerts"),alerts=d.alerts||[];
 alertBox.hidden=false;
 alertBox.innerHTML='<div class="panel-heading"><div><h3>Alertas</h3><p>Itens que merecem sua atenção</p></div><span class="alert-count">'+alerts.length+'</span></div><div class="dashboard-alert-list">'+(alerts.length?alerts.slice(0,3).map(a=>'<div class="dashboard-alert-row '+esc(a.type)+'"><span class="dashboard-alert-icon">'+(a.type==="overdue"?"!":a.type==="negative"?"↘":"◷")+'</span><div class="dashboard-alert-copy"><b>'+esc(a.title)+'</b><small>'+esc(a.description)+' · '+esc(a.detail)+'</small></div><strong>'+money(a.amount)+'</strong></div>').join(""):'<div class="empty-state">Nenhum alerta no momento. Seu planejamento está em dia.</div>')+'</div><button class="link-button alert-calendar-link" data-go="calendar">Ver calendário financeiro →</button>';
 $("#stat-balance").textContent=money(d.balance);
 $("#stat-balance").classList.toggle("negative",Number(d.balance)<0);
 $("#stat-balance-note").textContent=Number(d.balance)<0?"Saldo real negativo — revise as saídas registradas":"Saldo real das suas contas";
 $("#stat-income").textContent=money(d.incomeTotal??d.income);
 $("#stat-expense").textContent=money(d.expenseTotal??d.expense);
 const projectedValue=Number(d.projectedBalance??d.balance);
 $("#stat-pending").textContent=money(projectedValue);
 $("#stat-pending").classList.toggle("negative",projectedValue<0);
 $("#stat-pending-note").textContent=projectedValue<0?"Faltam "+money(Math.abs(projectedValue))+" para cobrir os compromissos":"Saldo após pendências, lembretes e despesas fixas";
 $("#period-expense-total").textContent=money(d.expenseTotal??d.expense);
 $("#period-expense-paid").textContent=money(d.expense);
 $("#period-expense-pending").textContent=money(d.pendingExpenseMonth||0);
 const expenses=d.expenseTransactions||[];
 $("#expense-transactions-preview").innerHTML=expenses.length?expenses.map(t=>{
  const label=({paid:"Pago",pending:"Pendente",overdue:"Atrasado"})[t.status]||t.status;
  const due=t.status==="paid"?t.occurred_on:(t.due_on||t.occurred_on);
  const detail=[t.category_name||"Sem categoria",t.account_name||"Sem conta vinculada",(t.status==="paid"?"Pago em ":"Venc. ")+dateBR(due)].join(" · ");
  const statusClass=t.status==="paid"?"":(t.status==="overdue"?" overdue":" pending");
  return '<div class="expense-list-row"><div class="expense-list-main"><div class="expense-list-title"><b>'+esc(t.description)+'</b><span class="status-pill'+statusClass+'">'+label+'</span></div><small>'+esc(detail)+'</small></div><strong class="expense-list-value">'+money(t.amount)+'</strong></div>';
 }).join(""):'<div class="empty-state">Nenhuma despesa lançada neste período. Use “Novo lançamento” para registrar uma despesa.</div>';
 const fixed=d.fixedExpenses||[];
 $("#fixed-expense-total").textContent=money(d.fixedExpenseTotal||0);
 $("#fixed-expense-count").textContent=String(fixed.length);
 const today=new Date(),todayStart=new Date(today.getFullYear(),today.getMonth(),today.getDate());
 $("#fixed-expenses-preview").innerHTML=fixed.length?fixed.map(x=>{
  const due=new Date(String(x.due_on).slice(0,10)+"T12:00:00"),hasOccurrence=Number(x.occurrences)>0,overdue=hasOccurrence&&due<todayStart;
  const label=({weekly:"Semanal",monthly:"Mensal",yearly:"Anual"}[x.frequency]||"Recorrente");
  const countLabel=x.occurrences>1?x.occurrences+" ocorrências previstas":x.occurrences===1?"1 ocorrência prevista":"Próximo vencimento fora do período";
  const detail=[dateBR(x.due_on),label,countLabel,x.account_name||x.category_name||"Sem conta vinculada"].join(" · ");
  const status=overdue?"Atrasada":hasOccurrence?"Prevista":"Próxima";
  const amount=Number(x.period_total)>0?x.period_total:x.amount;
  return '<div class="fixed-expense-row"><div class="fixed-expense-copy"><b>'+esc(x.description)+'</b><small>'+esc(detail)+'</small></div><span class="status-pill fixed-status '+(overdue?"overdue":"pending")+'">'+status+'</span><strong class="fixed-expense-value">'+money(amount)+'</strong></div>';
 }).join(""):'<div class="empty-state">Nenhuma despesa fixa cadastrada. <button class="link-button" data-go="recurring">Cadastrar despesa fixa →</button></div>';
 const chart=(d.chart||[]),by={};chart.forEach(x=>by[x.month]=x);
 const a=state.month.split("-").map(Number),items=[];
 for(let i=5;i>=0;i--){const dt=new Date(a[0],a[1]-1-i,1),key=dt.getFullYear()+"-"+String(dt.getMonth()+1).padStart(2,"0");items.push(Object.assign({month:key,label:dt.toLocaleDateString("pt-BR",{month:"short"}),income:0,expense:0},by[key]||{}));}
 const max=Math.max(1,...items.map(x=>Math.max(+x.income,+x.expense)));
 $("#cashflow-chart").innerHTML=items.map(x=>'<div class="chart-month"><div class="chart-bar" title="Receitas: '+money(x.income)+'" style="height:'+Math.max(2,+x.income/max*92)+'%"></div><div class="chart-bar expense" title="Despesas: '+money(x.expense)+'" style="height:'+Math.max(2,+x.expense/max*92)+'%"></div><small class="chart-month-label">'+esc(x.label.replace(".",""))+'</small></div>').join("");
 const cats=d.categories||[],total=cats.reduce((s,x)=>s+(+x.amount),0);
 $("#expense-categories").innerHTML=cats.length?cats.map(c=>'<div class="category-row"><span class="category-symbol">'+symbol(c.name)+'</span><div class="category-copy"><b>'+esc(c.name)+'</b><div class="mini-progress"><i style="width:'+(total?Math.max(2,+c.amount/total*100):0)+'%;background:'+( /^#[0-9a-f]{6}$/i.test(c.color||"")?c.color:"#71809a")+'"></i></div></div><span class="category-amount">'+money(c.amount)+'</span></div>').join(""):'<div class="empty-state">Nenhuma despesa registrada neste período.</div>';
 const transactions=d.transactions||[];
 $("#recent-transactions").innerHTML=transactions.length?transactions.map(t=>'<div class="transaction-row"><span class="transaction-symbol">'+(t.kind==="income"?"↙":t.kind==="transfer"?"⇄":"↗")+'</span><div class="transaction-copy"><b>'+esc(t.description)+'</b><small>'+esc(t.category_name||"Sem categoria")+' · '+dateBR(t.occurred_on)+'</small></div><span class="transaction-amount '+(t.kind==="income"?"positive":t.kind==="expense"?"negative":"")+'">'+(t.kind==="income"?"+":t.kind==="expense"?"−":"")+money(t.amount)+'</span></div>').join(""):'<div class="empty-state">Nenhum lançamento neste mês. Use “Novo lançamento” para começar.</div>';
 const upcoming=d.upcoming||[];
 $("#upcoming-list").innerHTML=upcoming.length?upcoming.map(t=>{const dt=t.due_on?new Date(String(t.due_on).slice(0,10)+"T12:00:00"):null;return '<div class="upcoming-row"><span class="due-date"><b>'+(dt?String(dt.getDate()).padStart(2,"0"):"—")+'</b><small>'+(dt?dt.toLocaleDateString("pt-BR",{month:"short"}):"data")+'</small></span><div class="upcoming-copy"><b>'+esc(t.description)+'</b><small>'+esc(t.category_name)+'</small></div><span class="transaction-amount '+(t.kind==="income"?"positive":"negative")+'">'+money(t.amount)+'</span></div>';}).join(""):'<div class="empty-state">Nenhuma conta pendente cadastrada.</div>';
 $("#budget-preview").innerHTML=(d.budgets||[]).length?d.budgets.slice(0,4).map(x=>budgetRow(x,false)).join(""):'<div class="empty-state">Defina um limite para começar a acompanhar.</div>';
 $("#goal-preview").innerHTML=(d.goals||[]).length?d.goals.map(x=>goalRow(x,false)).join(""):'<div class="empty-state">Crie sua primeira meta financeira.</div>';
 const activity=d.activity||[];
 $("#dashboard-activity-list").innerHTML=activity.length?activity.map(item=>{
  const labels={transaction:"Lançamento",account:"Conta",budget:"Orçamento",goal:"Meta",recurring:"Despesa fixa",reminder:"Lembrete"};
  const icons={transaction:"↕",account:"▣",budget:"◷",goal:"◎",recurring:"⟳",reminder:"◷"};
  const amount=item.amount===null||item.amount===undefined?"":money(item.amount);
  const detail=item.entity_type==="transaction"?(item.detail==="income"?"Receita":item.detail==="transfer"?"Transferência":"Despesa"):item.entity_type==="account"?"Conta bancária":item.entity_type==="budget"?"Limite mensal":item.entity_type==="goal"?"Objetivo financeiro":item.entity_type==="recurring"?"Recorrência":"Pagamento agendado";
  return '<div class="activity-row"><span class="activity-icon '+esc(item.entity_type)+'">'+(icons[item.entity_type]||"•")+'</span><div class="activity-copy"><b>'+esc(item.title)+'</b><small>'+esc(labels[item.entity_type]||"Atualização")+' · '+esc(detail)+' · '+dateBR(item.created_at)+'</small></div>'+(amount?'<strong>'+amount+'</strong>':'')+'</div>';
 }).join(""):'<div class="empty-state">As novas contas, lançamentos, orçamentos, metas e lembretes aparecerão aqui.</div>';

 renderDashboardAccounts();
 renderDashboardMiniCalendar();
}
function renderCalendar(){
 const events=state.calendarEvents||[],parts=state.month.split("-").map(Number),year=parts[0],month=parts[1],daysInMonth=new Date(year,month,0).getDate(),offset=(new Date(year,month-1,1).getDay()+6)%7;
 if(!state.calendarSelectedDate||state.calendarSelectedDate.slice(0,7)!==state.month)state.calendarSelectedDate=state.month+"-01";
 const byDate={};events.forEach(x=>{const key=String(x.event_date).slice(0,10);(byDate[key]||(byDate[key]=[])).push(x);});
 const weekdays=["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"],cells=[];
 for(let i=0;i<offset;i++)cells.push('<div class="calendar-day empty" aria-hidden="true"></div>');
 for(let day=1;day<=daysInMonth;day++){
  const key=state.month+"-"+String(day).padStart(2,"0"),items=byDate[key]||[],selected=key===state.calendarSelectedDate,classes=["calendar-day",selected?"selected":"",items.length?"has-events":""].filter(Boolean).join(" ");
  const dots=items.slice(0,3).map(x=>'<i class="'+(x.kind==="income"?"income":x.kind==="transfer"?"transfer":"expense")+'"></i>').join("");
  const total=items.filter(x=>x.kind==="expense").reduce((sum,x)=>sum+Number(x.amount||0),0);
  cells.push('<button type="button" class="'+classes+'" data-calendar-day="'+key+'"><span class="calendar-day-number">'+day+'</span><span class="calendar-dots">'+dots+'</span><small>'+(items.length?(items.length+" evento(s)"):"")+'</small>'+(total?'<b class="calendar-day-total">'+money(total)+'</b>':"")+'</button>');
 }
 const remainder=(7-(cells.length%7))%7;for(let i=0;i<remainder;i++)cells.push('<div class="calendar-day empty" aria-hidden="true"></div>');
 $("#calendar-weekdays").innerHTML=weekdays.map(x=>'<span>'+x+'</span>').join("");
 $("#calendar-grid").innerHTML=cells.join("");
 $("#calendar-month-label").textContent=monthName(state.month);
 const chosen=byDate[state.calendarSelectedDate]||[];
 $("#calendar-day-title").textContent=dateBR(state.calendarSelectedDate);
 $("#calendar-day-count").textContent=chosen.length+" evento(s)";
 const outflow=chosen.filter(x=>x.kind==="expense").reduce((sum,x)=>sum+Number(x.amount||0),0);
 $("#calendar-day-total").textContent=money(outflow);
 $("#calendar-day-events").innerHTML=chosen.length?chosen.map(x=>'<div class="calendar-event-row '+(x.source==="reminder"?"reminder-event":"")+'"><span class="calendar-event-icon '+(x.kind==="income"?"income":x.kind==="transfer"?"transfer":"expense")+'">'+(x.kind==="income"?"↙":x.kind==="transfer"?"⇄":"↗")+'</span><div class="calendar-event-copy"><b>'+esc(x.description)+'</b><small>'+esc(x.category_name||"Sem categoria")+' · '+esc(x.account_name||x.card_name||"Sem conta vinculada")+' · '+(x.source==="recurring"?"Prevista":x.source==="reminder"?"Lembrete de pagamento":statusPill(x.status))+'</small></div><strong class="'+(x.kind==="income"?"positive":x.kind==="expense"?"negative":"")+'">'+(x.kind==="income"?"+":x.kind==="expense"?"−":"")+money(x.amount)+'</strong>'+(x.source==="transaction"?'<button class="table-action edit" data-calendar-edit="'+esc(x.id)+'" title="Editar lançamento" aria-label="Editar lançamento">✎</button>':x.source==="reminder"?'<button class="table-action edit" data-calendar-edit-reminder="'+esc(x.id)+'" title="Editar lembrete" aria-label="Editar lembrete">✎</button><button class="table-action reminder-pay" data-reminder-pay="'+esc(x.id)+'" title="Registrar pagamento" aria-label="Registrar pagamento">✓</button><button class="table-action reminder-delete" data-delete="reminder" data-id="'+esc(x.id)+'" title="Excluir lembrete" aria-label="Excluir lembrete">×</button>':'<button class="table-action edit" data-calendar-recurring="'+esc(x.rule_id)+'" title="Ver recorrência">↗</button>')+'</div>').join(""):'<div class="empty-state">Nenhum compromisso neste dia. Aproveite para organizar seu planejamento.</div>';
}
function statusPill(s){const labels={paid:"Concluído",pending:"Pendente",overdue:"Atrasado",cancelled:"Cancelado"};return '<span class="status-pill '+(s==="pending"?"pending":s==="overdue"?"overdue":"")+'">'+(labels[s]||s)+'</span>';}
