function updateTransactionFields(){
 const k=$("#field-kind").value,account=$("#field-accountId"),status=$("#field-status"),card=$("#field-cardId"),destination=$("#field-transferToAccountId");
 const hide=(n,v)=>{const e=$("#field-"+n);if(e)e.closest(".field").hidden=v;};
 hide("categoryId",k==="transfer");hide("cardId",k!=="expense");hide("transferToAccountId",k!=="transfer");hide("installments",k!=="expense");
 const cat=$("#field-categoryId");if(cat){const selected=cat.value;cat.innerHTML=options([{value:"",label:"Sem categoria"},...state.categories.filter(c=>c.kind===(k==="income"?"income":"expense")).map(c=>({value:c.id,label:c.name}))],selected);}
 const syncAccountRequirement=()=>{
  const cardPurchase=k==="expense"&&!!card?.value&&status?.value!=="paid";
  if(account){account.closest(".field").hidden=cardPurchase;account.required=k==="transfer"||k==="income"||(k==="expense"&&!card?.value)||(k==="expense"&&status?.value==="paid");}
  if(destination)destination.required=k==="transfer";
 };
 if(status)status.onchange=syncAccountRequirement;
 if(card)card.onchange=()=>{
  if(k==="expense"&&card.value&&!state.editingTransactionId&&status?.value==="paid")status.value="pending";
  if(k==="expense"&&card.value&&account&&status?.value!=="paid")account.value="";
  syncAccountRequirement();
 };
 syncAccountRequirement();
}
