async function logout(){const button=$("#logout-button");button.disabled=true;try{await api("/api/auth/logout",{method:"POST"});Object.assign(state,{user:null,categories:[],accounts:[],cards:[],transactions:[],budgets:[],goals:[],recurring:[],dashboard:null,page:"dashboard"});$("#auth-form").reset();authMode("login");showAuth();toast("Você saiu da sua conta. Entre com outra conta.");}catch(err){toast("Não foi possível encerrar a sessão. Verifique sua conexão e tente novamente.",true);}finally{button.disabled=false;}}
