function exportCSV(){const rows=[["Descrição","Tipo","Categoria","Conta/Cartão","Data","Vencimento","Situação","Valor"],...state.transactions.map(t=>[t.description,t.kind,t.category_name,t.account_name||t.card_name,dateBR(t.occurred_on),dateBR(t.due_on),t.status,t.amount])];const csv="\ufeff"+rows.map(r=>r.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(";")).join("\r\n");const a=document.createElement("a"),u=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));a.href=u;a.download="tvc-control-"+state.month+".csv";a.click();URL.revokeObjectURL(u);}
